import java.util.Scanner;

/**
 * Variant 5: Using Scanner, with inline angle calculation
 */
public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        if (n > 11) {
            System.out.println(0);
            return;
        }
        Point[] points = new Point[n];
        for (int i = 0; i < n; i++) {
            int v = sc.nextInt();
            int w = sc.nextInt();
            int x = sc.nextInt();
            int y = sc.nextInt();
            int z = sc.nextInt();
            points[i] = new Point(v, w, x, y, z);
        }

        StringBuilder sb = new StringBuilder();
        int count = 0;
        for (int i = 0; i < n; i++) {
            boolean isGood = true;
            for (int j = 0; j < n; j++) {
                for (int k = 0; k < n; k++) {
                    if (i != j && i != k && j != k) {
                        Point one = points[j];
                        Point two = points[k];
                        Point three = points[i];

                        Point lol2 = new Point(one.v - three.v, one.w - three.w, one.x - three.x, one.y - three.y, one.z - three.z);
                        Point lol1 = new Point(two.v - three.v, two.w - three.w, two.x - three.x, two.y - three.y, two.z - three.z);

                        double dot = lol1.v * lol2.v + lol1.w * lol2.w + lol1.x * lol2.x + lol1.y * lol2.y + lol1.z * lol2.z;
                        double mag1 = Math.sqrt(lol1.v * lol1.v + lol1.w * lol1.w + lol1.x * lol1.x + lol1.y * lol1.y + lol1.z * lol1.z);
                        double mag2 = Math.sqrt(lol2.v * lol2.v + lol2.w * lol2.w + lol2.x * lol2.x + lol2.y * lol2.y + lol2.z * lol2.z);
                        double angleDeg = Math.toDegrees(Math.acos(dot / (mag1 * mag2)));
                        if (angleDeg < 90) {
                            isGood = false;
                        }
                    }
                }
            }
            if (isGood) {
                count++;
                sb.append(i + 1).append("\n");
            }
        }
        if (count == 0) {
            System.out.println(0);
        } else {
            System.out.println(count);
            System.out.print(sb.toString());
        }
    }

    static class Point {
        int v, w, x, y, z;
        Point(int v, int w, int x, int y, int z) {
            this.v = v; this.w = w; this.x = x; this.y = y; this.z = z;
        }
    }
}
